CREATE TABLE platform_comments(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,author_id uuid NOT NULL,content text NOT NULL CHECK(length(content) BETWEEN 1 AND 10000),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id));
ALTER TABLE platform_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant ON platform_comments USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON platform_comments TO orgmap_app;
CREATE TABLE platform_files(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,owner_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 0 AND 5242880),sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('STAGED','READY','REJECTED')),blob_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,owner_id) REFERENCES members(organization_id,id));
