CREATE TABLE platform_jobs(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,owner_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('EXPORT','IMPORT')),resource_type text NOT NULL,resource_ids uuid[] NOT NULL,export_kind text NOT NULL CHECK(export_kind IN ('RESOURCES','TASKS','STATISTICS')),format text NOT NULL DEFAULT 'JSON' CHECK(format IN ('JSON','CSV')),input jsonb,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','RUNNING','COMPLETED','FAILED','CANCELLED')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_token uuid,lease_until timestamptz,result jsonb,error_code text,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,owner_id) REFERENCES members(organization_id,id));
ALTER TABLE platform_jobs ENABLE ROW LEVEL SECURITY;
